"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations

from functools import lru_cache


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


_GLOBSTAR = "**"


def _compile_segment(seg: str) -> tuple:
    """Compile one path segment into a tuple of tokens."""
    tokens = []
    i = 0
    n = len(seg)
    while i < n:
        c = seg[i]
        if c == "\\":
            if i + 1 >= n:
                raise PatternError("dangling backslash")
            tokens.append(("lit", seg[i + 1]))
            i += 2
        elif c == "*":
            while i < n and seg[i] == "*":
                i += 1
            tokens.append(("star",))
        elif c == "?":
            tokens.append(("any",))
            i += 1
        elif c == "[":
            i += 1
            negate = False
            if i < n and seg[i] == "!":
                negate = True
                i += 1
            members = []  # (lo, hi) code point pairs
            first = True
            closed = False
            while i < n:
                c = seg[i]
                if c == "]" and not first:
                    closed = True
                    i += 1
                    break
                first = False
                if c == "\\":
                    if i + 1 >= n:
                        raise PatternError("unterminated character class")
                    c = seg[i + 1]
                    i += 2
                else:
                    i += 1
                if i + 1 < n and seg[i] == "-" and seg[i + 1] != "]":
                    i += 1
                    e = seg[i]
                    if e == "\\":
                        if i + 1 >= n:
                            raise PatternError("unterminated character class")
                        e = seg[i + 1]
                        i += 2
                    else:
                        i += 1
                    if ord(e) < ord(c):
                        raise PatternError("reversed range")
                    members.append((ord(c), ord(e)))
                else:
                    members.append((ord(c), ord(c)))
            if not closed:
                raise PatternError("unterminated character class")
            tokens.append(("class", negate, tuple(members)))
        else:
            tokens.append(("lit", c))
            i += 1
    return tuple(tokens)


def _token_matches(tok: tuple, ch: str) -> bool:
    kind = tok[0]
    if kind == "lit":
        return ch == tok[1]
    if kind == "any":
        return True
    o = ord(ch)
    found = any(lo <= o <= hi for lo, hi in tok[2])
    return found != tok[1]


def _match_segment(tokens: tuple, s: str) -> bool:
    n = len(tokens)
    states = {0}
    # expand leading stars
    def closure(st):
        out = set(st)
        for k in sorted(st):
            while k < n and tokens[k][0] == "star":
                k += 1
                out.add(k)
        return out

    states = closure(states)
    for ch in s:
        nxt = set()
        for k in states:
            if k >= n:
                continue
            tok = tokens[k]
            if tok[0] == "star":
                nxt.add(k)
            elif _token_matches(tok, ch):
                nxt.add(k + 1)
        if not nxt:
            return False
        states = closure(nxt)
    return n in states


def _match_path(segs: list, parts: list[str]) -> bool:
    ns, np_ = len(segs), len(parts)

    @lru_cache(maxsize=None)
    def go(i: int, j: int) -> bool:
        if i == ns:
            return j == np_
        seg = segs[i]
        if seg is _GLOBSTAR:
            if i == ns - 1:
                return np_ - j >= 1
            return any(go(i + 1, k) for k in range(j, np_ + 1))
        if j >= np_:
            return False
        return _match_segment(seg, parts[j]) and go(i + 1, j + 1)

    return go(0, 0)


def _strip_trailing_spaces(line: str) -> str:
    while line.endswith(" "):
        k = len(line) - 1
        bs = 0
        while k - 1 - bs >= 0 and line[k - 1 - bs] == "\\":
            bs += 1
        if bs % 2 == 1:
            break
        line = line[:-1]
    return line


def _compile(line: str):
    line = _strip_trailing_spaces(line)
    if not line or line.startswith("#"):
        return None
    negate = False
    if line.startswith("!"):
        negate = True
        line = line[1:]
    dir_only = False
    if line.endswith("/"):
        dir_only = True
        line = line[:-1]
    if not line:
        return None
    anchored = "/" in line
    if line.startswith("/"):
        line = line[1:]
    segs = []
    for raw in line.split("/"):
        if raw == "**":
            segs.append(_GLOBSTAR)
        else:
            segs.append(_compile_segment(raw))
    return negate, dir_only, anchored, segs


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [c for c in (_compile(p) for p in patterns) if c is not None]
    parts = path.split("/")
    result = False
    for negate, dir_only, anchored, segs in compiled:
        if dir_only and not is_dir:
            continue
        target = parts if anchored else parts[-1:]
        if _match_path(segs, target):
            result = not negate
    return result
